(function (global) {
  "use strict";
  var DATA = (global.ECON160_DATA && global.ECON160_DATA.generators) || {};

  function mulberry32(seed){ var a=seed>>>0; return function(){ a|=0; a=(a+0x6D2B79F5)|0;
    var t=Math.imul(a^(a>>>15),1|a); t=(t+Math.imul(t^(t>>>7),61|t))^t;
    return ((t^(t>>>14))>>>0)/4294967296; }; }
  function shuffleWithAnswer(rng, options, correctIdx){
    var idx=options.map(function(_,i){return i;});
    for(var i=idx.length-1;i>0;i--){ var j=Math.floor(rng()*(i+1)); var t=idx[i]; idx[i]=idx[j]; idx[j]=t; }
    var sh=idx.map(function(k){return options[k];});
    return { options:sh, correctIndex:idx.indexOf(correctIdx) };
  }
  function has(id){ return Object.prototype.hasOwnProperty.call(DATA,id); }

  function buildInstance(id, seed){
    var g=DATA[id]; if(!g){ return null; }
    var rng=mulberry32((seed>>>0)||1);
    var vi=Math.floor(rng()*g.versions.length);        /* one of five versions => random per student */
    var v=g.versions[vi];
    var sh=shuffleWithAnswer(rng, v.options, v.answer); /* also shuffle the 4 choices */
    var out={ id:id, kind:"mc", render:g.render, chapter:g.chapter, difficulty:g.difficulty,
      concept:g.concept, points:g.points||1, prompt:v.stem, options:sh.options,
      answer:sh.correctIndex, rationale:v.rationale||"", seed:(seed>>>0), version:(vi+1) };
    if(v.svg){ out.diagramSpec={ type:"econ160svg", svg:v.svg }; }
    return out;
  }

  /* ---- wrap IMGenerators (additive; our ids handled here, others delegate) ---- */
  var IG = global.IMGenerators || {};
  var oGen=IG.generate, oGrade=IG.grade, oList=IG.list;
  IG.generate=function(id, seed, cfg){ return has(id) ? buildInstance(id, seed) : (oGen?oGen.call(IG,id,seed,cfg):null); };
  IG.grade=function(id, seed, submitted, cfg){
    if(!has(id)){ return oGrade?oGrade.call(IG,id,seed,submitted,cfg):{error:"unknown item"}; }
    var q=buildInstance(id, seed); var pick=parseInt(submitted,10);
    var ok=(pick===q.answer); return { correct:ok, points:ok?q.points:0, expected:q.answer };
  };
  IG.list=function(){
    var base = oList ? oList.call(IG) : [];
    for(var k in DATA){ if(DATA.hasOwnProperty(k)){ var g=DATA[k];
      base.push({ id:k, chapter:g.chapter, kind:"mc", render:g.render, difficulty:g.difficulty, concept:g.concept, econ160:true }); } }
    return base;
  };
  global.IMGenerators = IG;

  /* ---- wrap IMDiagrams so our pre-rendered figures/tables/matrices show up ---- */
  var ID = global.IMDiagrams || {};
  var oRender = ID.render;
  ID.render = function(spec){ if(spec && spec.type==="econ160svg"){ return spec.svg; } return oRender?oRender.call(ID,spec):""; };
  global.IMDiagrams = ID;

  try{ console.log("Econ160 add-on ready: "+Object.keys(DATA).length+" generators (5 versions each)."); }catch(e){}
})(typeof window !== "undefined" ? window : this);
